// Studio > Moteur: the Bun runtime catalog (generated by `yolo generate` from vendor/bun) and the
// yolo-core probes of the desktop (aphrody_system_stats, aphrody_benchmark). It absorbed the former
// packages/engine/yolo/web demo page.
import { useState } from "react";
import { MONOREPO_BUN_CATALOG } from "../../generated/bun-catalog";
import { tauriInvoke } from "../../tauri-bridge";

interface SystemStats {
  os: string;
  arch: string;
  timestamp_ms: number;
}
interface BenchmarkResult {
  message: string;
  latency_us: number;
}

export const BENCHMARK_ITERATIONS = 100_000;

export function RuntimeStudio() {
  const [output, setOutput] = useState<string>("");
  const [busy, setBusy] = useState(false);
  const run = async (task: () => Promise<string>) => {
    setBusy(true);
    try {
      setOutput(await task());
    } catch (error) {
      setOutput(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };
  const probe = () =>
    run(async () => {
      const stats = await tauriInvoke<SystemStats>("aphrody_system_stats");
      if (!stats) return "Cette mesure nécessite l’application Aphrody.";
      return `${stats.os} ${stats.arch} · ${new Date(stats.timestamp_ms).toLocaleString()}`;
    });
  const bench = () =>
    run(async () => {
      const result = await tauriInvoke<BenchmarkResult>("aphrody_benchmark", {
        iterations: BENCHMARK_ITERATIONS,
      });
      if (!result) return "Cette mesure nécessite l’application Aphrody.";
      return `${result.message} · ${result.latency_us} µs`;
    });
  const catalog = MONOREPO_BUN_CATALOG;
  return (
    <div className="flex flex-col gap-6">
      <header className="flex flex-col gap-2">
        <h2 className="text-headline-small">Moteur</h2>
        <p className="max-w-prose text-on-surface-variant">
          Le runtime Bun d’Aphrody et les mesures du moteur natif de cette
          application.
        </p>
      </header>
      <section className="flex flex-col gap-3 rounded-large bg-surface-container-low p-6">
        <h3 className="text-title-large">Mesures</h3>
        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            disabled={busy}
            onClick={() => void probe()}
            className="min-h-12 rounded-full bg-primary px-6 text-label-large text-on-primary disabled:opacity-40"
          >
            Sonder l’hôte
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => void bench()}
            className="min-h-12 rounded-full border border-outline px-6 text-label-large text-primary hover:bg-primary/10 disabled:opacity-40"
          >
            Banc d’essai ({BENCHMARK_ITERATIONS.toLocaleString()} itérations)
          </button>
        </div>
        <output
          aria-live="polite"
          className="min-h-6 font-mono text-body-medium"
        >
          {output}
        </output>
      </section>
      <section className="flex flex-col gap-3">
        <h3 className="text-title-large">
          Bun {catalog.bunVersion}{" "}
          <span className="text-body-medium text-on-surface-variant">
            ({catalog.bunRevision.slice(0, 8)}, vendor/bun{" "}
            {catalog.sourceRevision.slice(0, 8)})
          </span>
        </h3>
        <ul className="grid gap-3 md:grid-cols-2">
          {catalog.capabilities.map((capability) => (
            <li
              key={capability.id}
              className="flex flex-col gap-2 rounded-large bg-surface-container-low p-4"
            >
              <span className="text-title-medium">{capability.title}</span>
              <span className="text-body-medium text-on-surface-variant">
                {capability.description}
              </span>
              <span className="font-mono text-body-medium text-primary">
                {capability.keyApis.join(" · ")}
              </span>
              <span className="text-body-medium text-on-surface-variant">
                {capability.docCount} pages de documentation
              </span>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}
